                continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in seen:
                        seen.add(p); q.append(p)
            comps.append(comp)
    for comp in comps:
        a=min(y for y,x in comp); b=max(y for y,x in comp)
        l=min(x for y,x in comp); rr=max(x for y,x in comp)
        area={(y,x) for y in range(a,b+1) for x in range(l,rr+1)}
        zeros=area-set(comp)
        fringe=[p for p in zeros if p[0] in (a,b) or p[1] in (l,rr)]
        exterior=set(fringe)
        while fringe:
            y,x=fringe.pop()
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(y+dy,x+dx)
                if p in zeros and p not in exterior:
                    exterior.add(p); fringe.append(p)
        holes=zeros-exterior
        if not holes:
            continue
        cy,cx=(a+b+1)//2,(l+rr)//2
        for y,x in holes:
            if (y,x)!=(cy,cx): out[y][x]=3
        # Color the one-cell 8-neighbour halo outside the closed outline.
        for y,x in comp:
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    ny,nx=y+dy,x+dx
