                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in seen:
                        seen.add(p); stack.append(p)
            a=min(y for y,x in comp); b=max(y for y,x in comp)
            l=min(x for y,x in comp); rr=max(x for y,x in comp)
            zeros={(y,x) for y in range(a,b+1) for x in range(l,rr+1) if grid[y][x]==0}
            q=[p for p in zeros if p[0] in (a,b) or p[1] in (l,rr)]
            outside=set(q)
