def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(y+dy,x+dx)
            if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==1 and p not in seen:
              seen.add(p); q.append(p)
        a=min(y for y,x in comp); b=max(y for y,x in comp)
        l=min(x for y,x in comp); rr=max(x for y,x in comp)
        zeros={(y,x) for y in range(a,b+1) for x in range(l,rr+1) if grid[y][x]==0}
        q=[p for p in zeros if p[0] in (a,b) or p[1] in (l,rr)]; ext=set(q)
        while q:
          y,x=q.pop()
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(y+dy,x+dx)
            if p in zeros and p not in ext: ext.add(p); q.append(p)
        holes=zeros-ext
        if not holes: continue
        cy,cx=(a+b+1)//2,(l+rr)//2
        for y,x in holes:
          if (y,x)!=(cy,cx): out[y][x]=3
        # Outer halo is the outline's 8-neighbor boundary, excluding its diagonals
        # in rows/columns where the original outline has a gap at that edge.
        for y,x in comp:
          for dy in (-1,0,1):
            for dx in (-1,0,1):
              ny,nx=y+dy,x+dx
              if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0 and (not (a<=ny<=b and l<=nx<=rr) or (ny,nx) in ext):
                out[ny][nx]=2
    return out

