 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Label 4-connected 1-components, which form the separate outline drawings.
    one_id = [[-1] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or one_id[r][c] >= 0:
                continue
            k = len(components)
            q = [(r, c)]
            one_id[r][c] = k
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and one_id[ny][nx] < 0:
                        one_id[ny][nx] = k
                        q.append((ny, nx))
            components.append(comp)

    # Find zero regions. Regions not connected to the grid edge are interior
    # cavities; paint them 3 while retaining their geometrical center pixel(s).
    zero_seen = set()
    framed_components = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in zero_seen:
                continue
            q = deque([(r, c)])
            zero_seen.add((r, c))
            region = []
            touches_edge = False
            adjacent_frames = set()
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < h and 0 <= nx < w):
                        continue
                    if grid[ny][nx] == 0 and (ny, nx) not in zero_seen:
                        zero_seen.add((ny, nx))
                        q.append((ny, nx))
                    elif grid[ny][nx] == 1:
                        adjacent_frames.add(one_id[ny][nx])
            if touches_edge:
                continue
            framed_components.update(adjacent_frames)
            min_r = min(y for y, x in region); max_r = max(y for y, x in region)
            min_c = min(x for y, x in region); max_c = max(x for y, x in region)
            center_rows = {(min_r + max_r) // 2, (min_r + max_r + 1) // 2}
            center_cols = {(min_c + max_c) // 2, (min_c + max_c + 1) // 2}
            centers = {(y, x) for y in center_rows for x in center_cols if (y, x) in set(region)}
            if not centers:
                # For an irregular cavity with no exact midpoint cell, preserve
                # the cell(s) closest to the bounding-box midpoint.
                dist = { (y, x): abs(2*y-min_r-max_r) + abs(2*x-min_c-max_c) for y, x in region }
                best = min(dist.values())
                centers = {p for p, d in dist.items() if d == best}
            for y, x in region:
                if (y, x) not in centers:
                    out[y][x] = 3

    # Color the exterior 8-neighbor halo around any outline that encloses a cavity.
    for k in framed_components:
        for y, x in components[k]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0:
                        # Do not overwrite filled cavity cells or their preserved center.
                        if out[ny][nx] == 0 and (ny == y and nx == x):
                            continue
                        # A global exterior zero is 2; enclosed zeros were already
                        # colored 3 (or left as the central aperture).
                        if (ny == 0 or nx == 0 or ny == h - 1 or nx == w - 1):
                            exterior = True
                        else:
                            # Determine connectivity to the grid edge for this cell.
                            exterior = False
                            todo = [(ny, nx)]; visited = {(ny, nx)}
                            while todo and not exterior:
                                yy, xx = todo.pop()
                                if yy == 0 or xx == 0 or yy == h - 1 or xx == w - 1:
                                    exterior = True
                                    break
                                for ddy, ddx in ((1,0),(-1,0),(0,1),(0,-1)):
                                    ay, ax = yy + ddy, xx + ddx
                                    if 0 <= ay < h and 0 <= ax < w and grid[ay][ax] == 0 and (ay,ax) not in visited:
                                        visited.add((ay,ax)); todo.append((ay,ax))
                        if exterior:
                            out[ny][nx] = 2
    return out

if __name__ == '__main__':
    print('transform ready')
