                continue
            k = len(components)
            labels[r][c] = k
            q = [(r, c)]
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and labels[ny][nx] == -1:
                        labels[ny][nx] = k
                        q.append((ny, nx))
            components.append(comp)

    # Exterior 0 regions and enclosed cavities, using 4-connectivity.
    seen = set()
    exterior = set()
    cavities = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            edge = False
            adjacent_components = set()
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y in (0, h-1) or x in (0, w-1):
                    edge = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
