                    if grid[ny][nx] == 0 and (ny, nx) not in seen:
                        seen.add((ny, nx)); q.append((ny, nx))
                    elif grid[ny][nx] == 1:
                        adjacent_components.add(labels[ny][nx])
            if edge:
                exterior.update(cells)
            else:
                cavities.append((cells, adjacent_components))

    closed_components = set()
    for cells, cids in cavities:
        closed_components.update(cids)
