    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    exterior = set()
    cavities = []
    # Eight-connected zero flow: diagonal leaks leave a frame open.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    edge = True
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y+dy, x+dx
                        if (dy or dx) and 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
            if edge: exterior.update(cells)
            else: cavities.append(set(cells))
    frame = set()
    for cavity in cavities:
        for y,x in cavity:
            out[y][x] = 3
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1:
                        frame.add((ny,nx))
    for y,x in frame:
        for dy in (-1,0,1):
            for dx in (-1,0,1):
                ny,nx=y+dy,x+dx
                if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0 and (ny,nx) in exterior:
                    out[ny][nx]=2
    return out

if __name__ == '__main__':
    print('ready')
